'use strict';

const util = require('util');
const javaio = require('java.io');
const zlib = require('zlib');
const SERIALIZED_BY_JAVA = 1;

javaio.addObject('com.alipay.config.common.protocol.NSwizzle', {
  readObject(io, obj) {
    io.readBlockHeader();
    io.readByte();
    const size = io.readInt();
    let buf = new Buffer(size);
    // 前面的 readByte readInt 已经读取了5个字节.
    io.readFully(buf, size, 5);
    // console.log(buf)
    let data;
    if (buf[0] === 0xac && buf[1] === 0xed) {
      data = javaio.InputObjectStream.readObject(buf);
    } else {
      // need to unzip
      // 1f 8b 08
      buf = zlib.gunzipSync(buf);
      // console.log(buf)
      data = javaio.InputObjectStream.readObject(buf);
      if (Array.isArray(data)) {
        data = data.map(function(buf) {
          return javaio.InputObjectStream.readObject(new Buffer(buf));
        });
      }
    }

    if (data && data.zoneData) {
      obj.$ = data.zoneData;
    } else {
      obj.$ = data;
    }
    return obj;
  },
  writeObject(io, obj) {
    let buf;
    if (obj.$ && util.isBuffer(obj.$.bytes)) {
      buf = obj.$.bytes;
    } else if (util.isString(obj.$)) {
      buf = javaio.OutputObjectStream.writeObject(obj.$);
    } else {
      throw new Error('Data can`t be empty.');
    }
    io.writeBlockHeader(buf.length + 5);
    io.out.put(SERIALIZED_BY_JAVA);
    io.writeInt(buf.length);
    io.out.put(buf);
  },
});
